<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">jmvcc</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> client</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> call</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> greet</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> Steve</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;[1,2]&#39;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;&quot;5&quot;&#39;</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">   # аргумент — JSON, если разбирается, иначе текст</span></span>
